import std.list as l
fn main(){var xs=l.from_slice([1,2])
var alias=xs
var copy=clone(xs)
print(unwrap(l.append(alias,3)),l.len(xs),l.snapshot(copy))
l.clear(alias)
print(l.len(xs),l.snapshot(copy))}

import std.list as l
fn main(){var xs=l.from_slice([1,2])
let before=l.snapshot(xs)
print(unwrap(l.set(xs,0,9)),unwrap(l.get(xs,0)),unwrap(l.extend(xs,before)))
print(unwrap(l.pop(xs)),l.snapshot(xs),before)
l.clear(xs)
print(l.len(xs),is_err(l.pop(xs)),before)}

